CREATE TABLE inbox (
    seq INTEGER PRIMARY KEY, update_id INTEGER NOT NULL UNIQUE,
    payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', received_at INTEGER NOT NULL
);
CREATE TABLE actions (
    action_key TEXT PRIMARY KEY, method TEXT NOT NULL,
    state TEXT NOT NULL, result TEXT, created_at INTEGER NOT NULL
);

CREATE TABLE cases (
    id INTEGER PRIMARY KEY, chat_id INTEGER NOT NULL, message_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL, domain TEXT NOT NULL, created_at INTEGER NOT NULL,
    voided INTEGER NOT NULL DEFAULT 0, deleted INTEGER NOT NULL DEFAULT 0,
    mute_until INTEGER, UNIQUE(chat_id,message_id)
);
CREATE TABLE moderation_log (
    id INTEGER PRIMARY KEY, case_id INTEGER, actor_id INTEGER,
    event TEXT NOT NULL, created_at INTEGER NOT NULL
);

SELECT * FROM cases WHERE id = 123;
SELECT actor_id,event,created_at FROM moderation_log WHERE case_id = 123 ORDER BY id;
SELECT action_key,state FROM actions WHERE action_key IN ('delete:123','mute:123');
